   :turn-test-reds/fresh-base-helper "(defn turn-cache-probe [label test-symbols]\n (let [thread (Thread/currentThread) entering (.getContextClassLoader thread)\n       connection (seon.operator/connection \"turn-test-cache\")]\n  (try\n   (.setContextClassLoader thread turn-cache-loader)\n   (with-bindings {clojure.lang.Compiler/LOADER turn-cache-loader}\n    (seon.schema/call-with-projection\n     (seon.db/carried-projection (seon.db/db connection))\n     (fn []\n      (let [manifest (seon.fn/build-manifest {:seon.fn/roots [\"src\" \"test\"]})\n            base (with-redefs-fn {#'seon.test-support/source-manifest (delay manifest)}\n                   #(#'seon.test-support/create-base nil))]\n       (try\n        (with-redefs-fn {(ns-resolve 'seon.test-support 'database-base) (delay base)}\n         (fn []\n          (mapv (fn [test-symbol]\n                  (let [result (seon.test/run (requiring-resolve test-symbol) connection\n                                {:seon.test/remaining-ms 120000\n                                 :seon.test.run/provenance\n                                 (seon.test.runner/provenance (seon.db/db connection))})]\n                   (spit (str \"/Users/sean/src/seon/tmp/turn-test-cache/\" label \"-\" (name test-symbol) \".edn\") (pr-str result))\n                   (select-keys result [:seon.test/sym :seon.test/pass-count :seon.test/fail-count\n                                        :seon.test/error-count :seon.test/run])))\n                test-symbols)))\n        (finally (#'seon.test-support/close-base! base)))))))\n   (finally (.setContextClassLoader thread entering)))))"
   :turn-test-reds/seed-probe "(do (binding [*ns* (the-ns 'seon.cluster.turn-test)] (eval '(deftest turn-cache-seed-probe (with-cluster (fn [cluster] (let [connection (:seon.db/connection cluster) seeds [[(agent-row \"peer\") {:seon.config/cluster \"turn-test\" :seon.config.run/max-episode-runs 2} {:seon.ns/name 'seon.config} {:seon.fn/sym \"seon.config/defaults\" :seon.fn/ns [:seon.ns/name 'seon.config] :seon.fn/source \"(defn defaults [] {})\" :seon.fn/spec \"[:=> [:cat] :map]\"}] [{:seon.config/cluster \"turn-test\" :seon.config.ai.retry/base-delay-ms 1 :seon.config.ai.retry/multiplier 2.0 :seon.config.ai.retry/jitter-fraction 0.0 :seon.config.ai.retry/maximum-delay-ms 4 :seon.config.ai.retry/maximum-retries 0 :seon.config.ai.retry/maximum-total-delay-ms 1000}]] results (mapv (fn [seed] (let [r (db/transact! connection seed)] {:turn-test-reds/seed seed :turn-test-reds/result (dissoc r :db-before :db-after)})) seeds)] (spit \"/Users/sean/src/seon/tmp/turn-test-cache/seeds.edn\" (pr-str results)) (doseq [r results] (is (not (:seon.error/kind (:turn-test-reds/result r)))))))))) :ready))"
   :turn-test-reds/phase-probe "(deftest turn-cache-phase-probe\n  (with-cluster\n    (fn [cluster]\n      (let [connection (:seon.db/connection cluster)\n            results\n            (mapv\n              (fn [phase]\n                (let [run-id (str \"phase-probe-\" (name phase))\n                      seed (db/transact! connection\n                             [{:seon.turn/id run-id\n                               :seon.turn/agent [:seon.agent/id \"agent-a\"]\n                               :seon.turn/opened-tx \"datomic.tx\"}\n                              {:seon.agent/id \"agent-a\"}])\n                      start (when (= phase :evaluate)\n                              (db/transact! connection\n                                (turn/receipt-start-tx\n                                  {:seon.turn/id run-id\n                                   :seon.cluster.eval/ordinal 0\n                                   :seon.cluster.eval/at now})))\n                      settled\n                      (turn/settle!\n                        (cond-> {:seon.turn.loop/cluster cluster\n                                 :seon.turn.loop/now now\n                                 :seon.agent/id \"agent-a\"\n                                 :seon.turn/id run-id\n                                 :seon.error/value\n                                 {:seon.error/kind (keyword \"seon.turn.phase\" (name phase))\n                                  :seon.error/message (str \"injected \" (name phase) \" failure\")\n                                  :seon.error/data {:seon.turn.loop/phase phase}}}\n                          (= phase :evaluate) (assoc :seon.cluster.eval/ordinal 0)))]\n                  {:turn-test-reds/phase phase\n                   :turn-test-reds/seed (dissoc seed :db-before :db-after)\n                   :turn-test-reds/start (dissoc start :db-before :db-after)\n                   :turn-test-reds/settled\n                   (update settled :seon.turn.loop/outcome dissoc :db-before :db-after)\n                   :turn-test-reds/turn (db/pull @connection '[*] [:seon.turn/id run-id])}))\n              [:claim :evaluate])]\n        (spit \"/Users/sean/src/seon/tmp/turn-test-cache/phase-probe.edn\" (pr-str results))\n        (doseq [result results]\n          (is (nil? (:seon.error/kind (:turn-test-reds/seed result))))\n          (is (some? (:seon.turn/closed-tx (:turn-test-reds/turn result)))))))))"
   :turn-test-reds/phase-observer "(deftest generated-phase-failures-converge-through-one-terminal-exit\n  (with-cluster fake-evaluate\n    (fn [cluster]\n      (let [connection (:seon.db/connection cluster)\n            sequence-number (atom 0)\n            cluster (assoc cluster :seon.config.error/escalate-to \"root\")\n            run-phases (schema/enum-members :seon.turn.loop/phase)]\n        (db/transact! connection [(agent-row \"root\")])\n        (test-support/assert-check!\n         (tc/quick-check\n          24\n          (prop/for-all [failed-phase (gen/elements run-phases)]\n            (let [sample (swap! sequence-number inc)\n                  run-id (str \"phase-failure-\" sample)\n                  evaluation? (= :evaluate failed-phase)\n                  failure {:seon.error/kind\n                           (keyword \"seon.turn.phase\"\n                                    (name failed-phase))\n                           :seon.error/message\n                           (str \"injected \" (name failed-phase) \" failure\")\n                           :seon.error/data {:seon.turn.loop/phase\n                                             failed-phase}}]\n              (db/transact!\n               connection\n               [{:seon.turn/id run-id :seon.turn/agent [:seon.agent/id \"agent-a\"] :seon.turn/opened-tx \"datomic.tx\"}\n                {:seon.agent/id \"agent-a\"\n                 }])\n              (when evaluation?\n                (db/transact!\n                 connection\n                 (turn/receipt-start-tx\n                  {:seon.turn/id run-id\n                   :seon.cluster.eval/ordinal 0\n                   :seon.cluster.eval/at now})))\n              (let [settled\n                    (turn/settle!\n                     (cond-> {:seon.turn.loop/cluster cluster\n                              :seon.turn.loop/now now\n                              :seon.agent/id \"agent-a\"\n                              :seon.turn/id run-id\n                              :seon.error/value failure}\n                       evaluation?\n                       (assoc :seon.cluster.eval/ordinal 0)))\n                    receipt-count\n                    (or\n                     (db/q '[:find (count ?receipt) .\n                             :in $ ?run-id\n                             :where\n                             [?run :seon.turn/id ?run-id]\n                             [?receipt :seon.cluster.eval/run ?run]]\n                           @connection run-id)\n                     0)]\n                (spit \"/Users/sean/src/seon/tmp/turn-test-cache/phase-observed-v2.edn\"\n                      (str (pr-str\n                            {:turn-test-reds/phase failed-phase\n                             :turn-test-reds/settled (update settled :seon.turn.loop/outcome dissoc :db-before :db-after)\n                             :turn-test-reds/evaluation-count receipt-count\n                             :turn-test-reds/turn (db/pull @connection '[*] [:seon.turn/id run-id])\n                             :turn-test-reds/closed-count\n                             (db/q '[:find (count ?closed) . :in $ ?run-id\n                                     :where [?run :seon.turn/id ?run-id]\n                                     [?run :seon.turn/closed-tx ?closed]]\n                                   @connection run-id)\n                             :turn-test-reds/errors\n                             (db/q '[:find (count ?error) .\n                                     :in $ ?run-id :where\n                                     [?run :seon.turn/id ?run-id]\n                                     [?error :seon.error/occurrences ?occurrence]\n                                     [?occurrence :seon.error.occurrence/turn ?run]]\n                                   @connection run-id)}) \"\\n\") :append true)\n                (and\n                 (some? settled)\n                 (= 1\n                    (db/q '[:find (count ?closed) .\n                            :in $ ?run-id\n                            :where\n                            [?run :seon.turn/id ?run-id]\n                            [?run :seon.turn/closed-tx ?closed]]\n                          @connection run-id))\n                 (= (if evaluation? 1 0) receipt-count)\n                 (= 1\n                    (db/q '[:find (count ?error) .\n                            :in $ ?run-id\n                            :where\n                            [?run :seon.turn/id ?run-id]\n                            [?error :seon.error.occurrences ?occurrence]\n                            [?occurrence :seon.error.occurrence/turn ?run]]\n                          @connection run-id))))))\n          :seed 2026080601)\n         \"Every injected phase failure must settle once, close once, and record\n          exactly one durable error fact.\")\n        ;; ESCALATION IS THE ONE BOUNDED OWNER'S, and this is where that is\n        ;; asserted — over the whole ledger the property just produced, not\n        ;; per sample. `seon.turn/refusal-terminal-data` used to\n        ;; `dissoc` the escalation dial and hand-roll one unbounded\n        ;; `\"A run phase failed: …\"` message per failure; that second copy is\n        ;; deleted, and the surviving behavior is what these queries state:\n        ;; one message per SIGNATURE at the recurrence limit, addressed to the\n        ;; escalation owner, and never to the agent whose run was refused.\n        (let [db @connection\n              faults (db/q '[:find ?to ?signature\n                             :keys :seon.agent/id :seon.error/signature\n                             :where\n                             [?message :seon.message/about ?error]\n                             [?message :seon.message/to ?agent]\n                             [?agent :seon.agent/id ?to]\n                             [?error :seon.error/signature ?signature]]\n                           db)\n              signatures (db/q '[:find ?signature\n                                 :where\n                                 [?error :seon.error/signature ?signature]\n                                 [?error :seon.error/occurrences ?occurrence]\n                                 [?occurrence :seon.error.occurrence/turn _]]\n                               db)]\n          (is (seq faults)\n              \"the escalation dial is on: a supervisor does hear about a\n               worker's refused phases, which is the whole point of it\")\n          (is (= #{\"root\"} (into #{} (map :seon.agent/id) faults))\n              \"only the escalation owner is mailed; the failing agent is never\n               told about its own refusal, because delivery is the wake\n               attribute and that message would wake the same unfixed cause\")\n          (is (every? #(= 1 %) (vals (frequencies (map :seon.error/signature\n                                                       faults))))\n              \"one escalation per signature per process — the storm fence.\n               Twenty-four failures over six phases may not be twenty-four\n               messages\")\n          (is (<= (count faults) (count signatures))\n              \"and never more messages than there are distinct signatures\"))))))"
